{"results": [{"id": "hp_doc_a194879bfeb3bf417d246ee42b3256fed1bf855382c0ada561d6de03d06d8108", "title": "Carrie Ann Inaba", "text": "Carrie Ann Inaba (born January 5, 1968) is an American dancer, choreographer, television dance competition judge, actress, game show host, and singer. She is best known for her work on ABC TV's \"Dancing with the Stars\".", "score": 38.5226}, {"id": "hp_doc_c6faa95251c890601c2328a284ee28a450a74b117bf6e634eda13aacf0524b57", "title": "Dance War: Bruno vs. Carrie Ann", "text": "Dance War: Bruno vs. Carrie Ann was an American reality TV show dance competition featuring choreographers Bruno Tonioli and Carrie Ann Inaba, two of the four \"Dancing with the Stars\" judges. Drew Lachey, \"Dancing with the Stars\" Season Two Champion, hosted the show.", "score": 31.4709}, {"id": "hp_doc_f55f5893aecc8e46fa25a137876e174c66981fb525095d228acf501518b2e380", "title": "Dancing with the Stars (U.S. season 22)", "text": "Season twenty-two of \"Dancing with the Stars\" premiered March 21, 2016, on the ABC network. Hosts Tom Bergeron and Erin Andrews returned, as did judges Carrie Ann Inaba and Bruno Tonioli. Len Goodman returned as head judge, after being absent for the previous season.", "score": 25.6486}], "remaining_searches": 2}
